import { isUndefined } from 'lodash-es';
import { useCallback } from 'react';

import { useCanvas } from '../../../../core/components/canvas/hooks/useCanvas.js';

interface CanvasCircleRendererProps {
  x: number;
  y: number;
  radius: number;
  fillColor: string;
  strokeColor?: 'transparent' | string;
}

export const CanvasCircleRenderer = (props: CanvasCircleRendererProps) => {
  const { x, y, radius, fillColor, strokeColor } = props;

  const draw = useCallback(
    (ctx: CanvasRenderingContext2D) => {
      ctx.fillStyle = fillColor;
      ctx.beginPath();
      ctx.arc(x, y, radius, 0, 2 * Math.PI);
      ctx.closePath();
      if (strokeColor === 'transparent') {
        ctx.globalCompositeOperation = 'destination-out';
        ctx.stroke();
        ctx.globalCompositeOperation = 'source-over';
      } else if (!isUndefined(strokeColor)) {
        ctx.strokeStyle = strokeColor;
        ctx.stroke();
      }
      ctx.fill();

      return false;
    },
    [x, y, radius, fillColor, strokeColor],
  );

  useCanvas('honeycomb-circle', draw);

  return null;
};

CanvasCircleRenderer['displayName'] = 'CanvasCircleRenderer';
